package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Xo'roz yoki eshakni eshitish", "Allohim, sendan fazlu fazlingni so'rayman (xo'roz). — Men la’nati (eshak) shaytondan Allohdan panoh tilayman.", "Xo'rozni eshitib, Allohdan fazl so'rang; eshakning qichqirayotganini eshitib, shaytondan panoh so'raydi.", "Xo‘roz farishtani, eshak shaytonni ko‘radi."),
        "dua_something_liked" to DuaText("Ajoyib narsani ko'rish (yomon ko'zga qarshi)", "Alloh xohlagan narsani. Allohim baraka bergin.", "Biror kishiga tegishli narsalarni ko'rsangiz, duo qiling.", "Baraka so'rab duo qilish yomon ko'zdan saqlaydi."),
        "dua_sell_buy_debt_repaid" to DuaText("Qarzni to'lashda", "Alloh oilangizga, molingizga baraka bersin.", "Qarzni to'lashda qarz beruvchi uchun.", "Kreditning qaytarilishi rahmat va to'lovdir."),
        "dua_talbiyah" to DuaText("Talbiya", "Mana, Allohim, mana men. Mana men, Sening sheriging yo'q, men shu yerdaman. Albatta, barcha hamdu sanolar, barakalar va hukmronlik Senikidir. Sizning sherigingiz yo'q.", "Ehromga kirgandan keyin baland ovozda.", "Haj va Umra timsoli."),
        "dua_yamani_hajar" to DuaText("Rukn Yamaniy va Hajar Asvad o'rtasida", "Ey Robbimiz, bizga bu dunyoda ham, oxiratda ham yaxshilik ato et va bizni do'zax azobidan saqla.", "Tavofda, Yaman burchagi va Qora tosh o'rtasida.", "Rasululloh ﷺ tavofda shu joyda buni o'qidilar."),
        "dua_safa_marwa" to DuaText("Safo va Marvada", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir va U har bir narsaga qodirdir. Allohdan boshqa hech kim ibodat qilinishga loyiq emas. U O'z va'dasini bajardi, bandasiga yordam berdi va bir o'zi ittifoqchilarni mag'lub etdi.", "Safoga chiqish va qiblaga yuzlanish (uch marta).", "Payg'ambarimiz zikri ﷺ Safo va Marva."),
        "dua_arafah" to DuaText("Arafa kunining eng yaxshi duosi", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir va U har bir narsaga qodirdir.", "Arafa kuni eng yaxshi duodir.", "Duoning eng yaxshisi Arafa kunining duosidir, eng yaxshisi esa shulardir."),
        "dua_takbeer_tashreeq" to DuaText("Takbir-i-tashrik", "Alloh buyukdir, Alloh eng buyukdir. Allohdan o'zga iloh yo'q. Alloh buyukdir, Alloh buyukdir va barcha hamdlar Allohga bo'lsin.", "Zulhijjaning 9-bomdosidan boshlab 13-zulhijjaning asriga qadar har bir farz namozidan keyin.", "Ali va Ibn Mas'uddan rivoyat (RA) — Hanafiylarga ko'ra vojib."),
        "dua_zamzam" to DuaText("Zamzam ichish", "Allohim, sendan foydali ilm, ko'p rizq va har bir dardga shifo so'rayman.", "Zamzam ichayotganda, nima niyat qilsangiz, duo qiling.", "Zamzam nima uchun ichilsa, shu uchundir (Ibn Moja 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Yaratilish haqida fikr yuritish", "Ey Robbimiz, bularning hammasini bekorga yaratmagansan. Sen poksan, bizni do'zax azobidan saqla.", "Osmonlar va yerning yaratilishi haqida fikr yurituvchilarning duosi.", "Aql egalarining duosi (ulul-albob)."),
        "dua_q_sami_na_munadiyan" to DuaText("Biz iymonga chorlovchini eshitdik", "Ey Robbimiz, biz iymonga chorlovchining «Robbingga iymon keltir», deganini eshitdik va iymon keltirdik. Ey Robbimiz, gunohlarimizni mag‘firat qil, gunohlarimizni o‘chir va bizni solihlar bilan birga o‘ldir.", "Imon va solihlar orasida o'lish uchun duo.", "Kechirim va yaxshi yakun uchun duo."),
        "dua_q_atina_ma_waadtana" to DuaText("Bizga va'da qilgan narsangni bergin", "Ey Robbimiz, bizga payg‘ambarlaring orqali va’da qilgan narsangni bergin va bizni qiyomat kuni sharmanda qilma. Albatta, Sen va'daingni buzmassan.", "Qiyomat kuni sharmandalikdan panoh top.", "Oxiratda izzat izlab."),
        "dua_q_israfana" to DuaText("Ortiqcha qilganlarimizni kechir", "Ey Robbimiz, gunohlarimizni va ishlarimizdagi haddan oshganlarimizni mag'firat qil, oyoqlarimizni mustahkam qil va kofir qavmga qarshi bizga yordam ber.", "Avvalgi payg'ambarlar sahobalarining duosi.", "Sabr va kechirim uchun duo."),
        "dua_q_jamiun_nas" to DuaText("Siz insoniyatni to'playsiz", "Ey Robbimiz, Sen odamlarni borligiga shak-shubha bo'lmagan kunda jamlaysan. Albatta, Alloh va'dasiga xilof qilmas.", "Qiyomat kunida aniqlikni tasdiqlash.", "Ilmga mustahkam asos solganlarning duosi."),
        "dua_q_maash_shahidin" to DuaText("Bizni guvohlar qatoriga yozing", "Ey Robbimiz, biz iymon keltirdik. Bas, bizni guvohlar qatoriga yozgin.", "Haqni tan olgan va iymon keltirganlarning duosi.", "Imonini qabul qilish uchun duo."),
        "dua_q_la_tajalna_zalimin" to DuaText("Zolimlar bilan emas", "Ey Robbimiz, bizlarni zolim qavm bilan birga qilma.", "A'rof ahlining duosi.", "Zolimlarning taqdiridan panoh."),
        "dua_q_tawaffana_muslimin" to DuaText("Musulmon sifatida sabr va o'lim", "Ey Robbimiz, ustimizdan sabr yog'dir va bizlarni musulmon holimizda o'ldirgin.", "Fir'avn sehrgarlarining iymon keltirganlarida qilgan duolari.", "Sinovda sabr va iymon bilan yakun."),
        "dua_q_la_tajalna_fitnah" to DuaText("Zolimlar uchun sinov emas", "Allohga tavakkul qilamiz. Ey Robbimiz, bizni zolim qavm uchun fitna qilma va bizni rahmating ila kofir qavmlardan qutqargin.", "Muso alayhissalomning duosi (AS).", "Zulm va zolimlardan qutulish uchun duo."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Nuh duosi (AS) kechirim so'rab", "Ey Robbim, sendan o‘zim bilmagan narsani so‘rashdan panoh tilayman. Va agar meni mag'firat qilmasang va rahm qilmasang, ziyon ko'rganlardan bo'laman.", "Nuh payg'ambarning tavba duosi (AS).", "To'g'ri odob bilan so'rash darsi."),
        "dua_q_mudkhala_sidq" to DuaText("Haqiqatning kirishi va chiqishi", "Ey Robbim, meni haq bilan kiritgin va haq bilan chiqargin va menga O'z huzuringdan yordam beruvchi hujjat ber.", "Yangi vazifaga, uyga yoki joyga kirishdan oldin.", "Hijrat davrida Payg'ambarga o'rgatilgan duo ﷺ."),
        "dua_q_la_tadharni_fardan" to DuaText("Zakariya duosi (AS) — Meni yolg'iz qo'yma", "Parvardigorim, meni yolg‘iz qo‘ymagin, Sen vorislarning eng yaxshisisan.", "Farzand izlayotganlar uchun.", "Bu duo orqali Alloh taolo Yahyoga (AS) ta ato etdi."),
        "dua_q_munzalan_mubarakan" to DuaText("Muborak qo'nish joyi", "Parvardigorim, meni muborak bir qo‘nim joyiga qo‘ygin, sen qo‘nganlarning eng yaxshisisan.", "Yangi uyga ko'chib o'tishda yoki biror joyda to'xtashda - Nuh duosi (AS).", "Yangi joyda baraka olish uchun duo."),
        "dua_q_amanna_faghfir" to DuaText("Biz ishonamiz, shuning uchun bizni kechir", "Ey Robbimiz, biz iymon keltirdik, bas, bizni mag‘firat qil va bizga rahm qil, Sen rahmlilarning eng yaxshisisan.", "Allohning solih bandalarining duosi.", "Kechirim va rahm-shafqat uchun keng qamrovli duo."),
        "dua_q_isrif_jahannam" to DuaText("Jahannam azobidan qaytaring", "Ey Robbimiz, bizdan do'zax azobini daf qilgin. Albatta, uning azobi doimiydir. Albatta, u yomon maskan va qarorgohdir.", "Rohman bandalarining duosi (Ibod ar-Rahmon).", "Do'zaxdan panoh uchun Qur'on duosi."),
        "dua_q_hab_li_hukman" to DuaText("Ibrohim duosi (AS) — Hikmat va jannat", "Parvardigorim, menga hikmat ato et va meni solihlar qatoriga qo‘sh, keyingi avlodlar orasida meni hurmatli qil va meni ne’matlar jannatining vorislaridan qil.", "Hikmat so'rab, solihlar hamrohi va jannat.", "Ibrohim alayhissalomning keng duosi (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Lut duosi (AS) - Oilamni qutqar", "Ey Robbim, meni va oilamni ular qilayotgan amallaridan saqla.", "O'z oilasini yomon muhitdan himoya qilish.", "Oilani yomonlikdan himoya qilish."),
        "dua_q_sulaiman_awzini" to DuaText("Sulaymon duosi (AS) Shukrona uchun", "Parvardigorim, menga va ota-onamga bergan ne’matingga shukr qilishimga, O‘zing rozi bo‘ladigan solih amallar qilishga va rahmating ila meni solih bandalaring qatoriga kiritgin.", "Ne'matlarga shukr qilish qobiliyati uchun.", "Sulaymonning rahmat duosi (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Muso alayhissalom duosi (AS) — Oʻzimga zulm qildim", "Ey Robbim, men o‘zimga zulm qildim, meni kechirgin.", "Xatodan keyin darhol tavba qilish.", "Alloh taolo Muso alayhissalomni kechirdi (AS)."),
        "dua_q_musa_najjini" to DuaText("Muso alayhissalom duosi (AS) - Meni zolimlardan qutqar", "Robbim, meni zolim qavmlardan saqla.", "Zolimlardan qo'rqqanda.", "Muso alayhissalomning Misrni tark etgandagi duosi (AS)."),
        "dua_q_lut_unsurni" to DuaText("Lut duosi (AS) - Buzg'unchilarga qarshi yordam", "Robbim, buzg'unchi qavmga qarshi menga yordam ber.", "Korruptsiyani tarqatganlarga qarshi yordam uchun.", "Haqda sobit bo'lganlarning duosi."),
        "dua_q_hab_li_salihin" to DuaText("Solih farzand uchun Ibrohim duosi (AS)", "Robbim, menga solihlardan (farzand) bergin.", "Solih bolalarni so'rash.", "Bu duo orqali Ismoil (AS) ta duo qilingan."),
        "dua_q_wasita_kulla_shay" to DuaText("Arsh ko'targan farishtalarning duosi", "Ey Robbimiz, Sen hamma narsani rahmat va ilm bilan o'rab olgansan, bas, tavba qilib, sening yo'lingga ergashganlarni mag'firat qil va ularni do'zax azobidan saqla.", "Arshni ko'targan farishtalar mo'minlar uchun duo qiladilar.", "Farishtalar duosiga qo'shilish niyatida o'qiladi."),
        "dua_q_ikhwanina" to DuaText("Bizdan Oldin O'tgan Birodarlarimizga", "Ey Robbimiz, bizlarni va bizdan oldin iymonda o‘tgan birodarlarimizni mag‘firat qil va qalblarimizda iymon keltirgan zotlarga nisbatan g‘azabni qo‘yma. Robbimiz, albatta, Sen mehribon va rahmlisan.", "Oldin kelgan mo'minlar uchun va toza qalb uchun duo.", "Sahobai sahobalar va avvalgi mo'minlar uchun duo (RA)."),
        "dua_q_alayka_tawakkalna" to DuaText("Senga suyanamiz (Ibrohim alayhissalom)", "Ey Robbimiz, Senga tavakkul qilamiz, Senga tavba qilamiz va qaytish Sengadir. Ey Robbimiz, bizni kofirlar uchun fitna qilma va bizni mag'firat qil. Robbimiz, albatta, Sen aziz va hikmatli zotsan.", "Ibrohim duosi (AS) va uning sahobalari.", "Allohga tavakkul qilish va Unga yuzlanish duosi."),
        "dua_q_atmim_nurana" to DuaText("Bizning nurimizni mukammal qiling", "Ey Robbimiz, biz uchun nurimizni mukammal qil va bizlarni mag'firat qil. Albatta, Sen har narsaga qodirsan.", "Mo'minlarning qiyomat kunidagi duosi.", "Sirotga nur so'rash."),
        "dua_q_asiya_baytan" to DuaText("Osiyo duosi — Jannatdagi uy", "Ey Robbim, men uchun O'z huzuringda jannatdan bir uy qurgin, meni Fir'avn va uning amallaridan saqlagin va meni zolim qavmlardan saqlagin.", "Fir'avnning xotini Osiyaning duosi.", "Alloh uni mo'minlar uchun namuna qilib qo'ydi."),
        "dua_adhan_response" to DuaText("Azonga javob berish", "Allohdan boshqa hech qanday kuch va kuch yo'q.", "Muazzin aytganlarini takrorlang; “Hayya alas-saloh” va “Hayya “alal-falah”da shunday deydilar.", "Kim yurakdan javob bersa, jannatga kiradi."),
        "dua_adhan_shahadah" to DuaText("Muazzinning shahodatidan keyin", "Va men ham guvohlik beramanki, Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q va Muhammad ﷺ Uning bandasi va rasulidir. Men Allohdan Robbim, Muhammaddan ﷺ Payg'ambarim va Islom dinimdan roziman.", "Muazzinning iymon shahodatini eshitib.", "Uning gunohlari kechiriladi."),
        "dua_istiftah_baid" to DuaText("Duoning ochilishi: Meni gunohlardan uzoqlashtir", "Allohim, mashriqni gʻarbdan uzoqlashtirganingdek, meni gunohlarimdan uzoq qil. Allohim, oq kiyim kirdan tozalanganidek, meni ham gunohlardan pok qil. Allohim, gunohlarimni suv, qor va do‘l bilan yuvib tashla.", "Ochilgan takbirdan keyin (Sano o'rnida ham aytish mumkin).", "Rasululloh ﷺ buni takbir bilan qiroat orasida aytdilar."),
        "dua_hamdan_kathiran" to DuaText("Rukudan keyin ko'p maqtov", "Robbimiz, hamd Senga xosdir – ko'p, pok va muborak hamd.", "Rukudan turgach, “Rabbana lakal-hamd” bilan birga.", "O'ttizdan ortiq farishtalar buni birinchi bo'lib yozib olish uchun poyga qilishdi."),
    )
}
